# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
T=[['拉丁 terra','土地、泥土、大地']]
TY=[['拉丁 territorium','城镇周边的土地、管辖区；常联系 terra，但更早构词仍有争论'],['中古英语 territorie → territory','管辖土地 → 领地、负责或熟悉的范围']]
TL=TY[:1]+[['晚期拉丁 territorialis → 英语 territorial','领地的；维护自己范围的']]
TR=T+[['拉丁 terrenus／terrenum → 法语 terrain','土地的 → 土地、地面'],['英语 terrain','地形、地面条件']]
TC=T+[['重建的通俗拉丁 *terracea → 法语 terrasse','土筑的台地、抬高的平台'],['英语 terrace','台地、露台；又有连排住宅等支线']]
def A(h,w,m):return h+[[w,m]]
WA=[
E('territory','英 /ˈterɪtəri/；美 /ˈterətɔːri/','领土；领地；负责或熟悉的范围','画一个圈：这里由谁管，谁在这里活动，或者谁对这块事情最熟悉。','接拉丁 territorium“城镇周边土地、管辖区”。通常联系 terra“土地”，但拉丁词的具体形成仍有争论，不把 terri + tory 当成已证实的历史拆法。',TY,'an animal’s territory 是它占据、维护的活动区域；sales territory 是销售人员负责的地区；unfamiliar territory 可以是陌生的知识或经历。土地的边界感逐渐变成“属于谁处理的范围”。','enter a territory；sales territory；unfamiliar territory；come with the territory。','terrain 说地面是什么样；territory 更常说这块范围归谁管、由谁活动。come with the territory 表示某种处境自然会带来某些问题。',('The sales team divided the country into five territories.','销售团队把全国划成了五个负责区域。'),('For me, managing a large team was unfamiliar territory.','对我来说，管理大团队是一个陌生领域。'),sources=['https://www.etymonline.com/word/territory']),
E('territorial','英 /ˌterɪˈtɔːriəl/；美 /ˌterəˈtɔːriəl/','领土的；领地性的；护地盘的','强调某块范围属于自己，或与某个地理辖区有关。','接晚期拉丁 territorialis；现代可按 territory 与 -al 联系，历史上是相应拉丁形容词的借入。',TL,'territorial boundaries 是领土或辖区界线；a territorial animal 会维护自己的活动区域；be territorial about a desk 可以形容人不愿别人碰自己的桌子。具体意思由后面的对象决定。','territorial boundaries；territorial behaviour；territorial about。','territorial 可是中性的地理分类，也可说维护地盘的态度；不是每次都表示侵略或争吵。',('The map marks the territorial boundaries in red.','地图用红色标出了辖区边界。'),('He is rather territorial about his workspace.','他很护自己的工作空间，不太愿意别人动。')),
E('territoriality','/ˌterɪˌtɔːriˈæləti/','领地性；维护地盘的行为；属地性','不只划出一个圈，还会把这个圈认作自己的范围并加以维护。','territorial + -ity，表示相关性质或行为模式。',A(TL,'英语 territoriality','领地性质；占据、维护领地的行为'),'动物行为里的 territoriality 是占据、标示或防卫领地的行为模式。谈人时可比喻护地盘、护职责范围；法律文字里的属地性则讨论权力或规则与地点的关系，需依上下文区分。','animal territoriality；territoriality in the workplace；the principle of territoriality。','territory 是那块区域；territoriality 是围绕区域表现出的性质、行为或原则。',('The students observed territoriality in the birds near the pond.','学生观察了池塘附近鸟类的领地行为。'),('Office territoriality made it harder for the departments to cooperate.','办公室里的护地盘心态让部门合作更困难。')),
E('territorially','英 /ˌterɪˈtɔːriəli/；美 /ˌterəˈtɔːriəli/','在领土或地域上；以维护地盘的方式','从空间范围来看，或者像在守住自己的地盘一样行动。','territorial + -ly。',A(TL,'英语 territorially','从领土、地域角度；按领地行为方式'),'territorially divided 说按地域划分；behave territorially 说表现出维护领地或职责地盘的行为。它描述观察角度或行为方式，本身不说明具体边界在哪。','territorially organised；territorially distinct；behave territorially。','geographically 是按地理看；territorially 往往还带辖区、控制或维护范围的意思。',('The service is organised territorially into local units.','这项服务按地域组织成各个地方单位。'),('The birds behaved territorially when another pair approached.','另一对鸟靠近时，这些鸟表现出了护领地的行为。')),
E('territorialism','/ˌterɪˈtɔːriəlɪzəm/','领地主义、属地主义；护地盘倾向〔随语境而异〕','把土地或辖区看成权力和制度的基础，或把自己的范围守得很紧。','territorial + -ism，形成观念、制度或倾向名称。',A(TL,'英语 territorialism','以领地为基础的制度、主张；维护自身范围的倾向'),'历史文字里可说地主阶层占主导的制度，也可特指领地主宰宗教安排的旧主张。现代组织评论有时用它批评部门各守一摊。遇到这个词，先看作者谈制度、宗教史还是职场行为。','territorialism in an organisation；a doctrine of territorialism。','territoriality 常描述领地行为或属地性质；territorialism 更容易强调观念、制度或带批评意味的护地盘倾向。',('The chapter examines territorialism in early modern religious politics.','这一章考察了近代早期宗教政治中的领地主义。'),('The manager wanted to reduce territorialism between departments.','经理希望减少部门之间各守地盘的倾向。'),sources=['https://www.collinsdictionary.com/dictionary/english/territorialism','https://www.merriam-webster.com/dictionary/territorialism']),
E('territorialist','/ˌterɪˈtɔːriəlɪst/','领地主义者；属地主义支持者〔历史、学术用语〕','把某种以领地为基础的制度主张放到一个支持者身上。','与 territorialism 对应，以 -ist 表示支持某种主张的人。',A(TL,'英语 territorialism／territorialist','领地主义等主张／其支持者'),'在历史文本中可指支持地主阶层主导制度的人，也可指支持领地政府决定宗教安排的旧理论者。具体标签随所讨论的理论而定，不要把所有维护自己桌位的人都叫 territorialist。','a territorialist argument；a territorialist writer。','territorialist 是某类主张的支持者；landowner 只是土地所有者，两种身份不自动相同。',('The historian compared the territorialist’s argument with that of his critics.','历史学家比较了那位领地主义者与其批评者的论点。'),('The essay explains why the writer was described as a territorialist.','文章解释了为什么那位作者被称为领地主义者。'),sources=['https://www.collinsdictionary.com/dictionary/english/territorialist']),
E('extraterritoriality','/ˌekstrəˌterɪˌtɔːriˈæləti/','治外法权；域外适用、域外性〔依语境〕','人或事情已经跨过地域边界，法律权力的作用却未必随边界整齐停止。','extra-“在外” + territorial + -ity，组成与通常地域范围之外有关的性质名称。',TL+[['英语 extra- + territorial → extraterritorial','地域、领土之外的'],['英语 extraterritoriality','超出通常属地关系的法律地位或适用问题']],'历史上常用来指某些人不受所在地法院或法律通常管辖的特权；现代法律讨论里也常涉及一国法律向境外事项的适用。两种语境有关却不相同，不能一律只翻成某一项具体特权。','the issue of extraterritoriality；a claim of extraterritoriality。','extraterritoriality 谈的是法律与地域的关系，不等于一块地方在物理上被搬到国外。读文章时先辨别是在谈豁免还是域外适用。',('The history course included a discussion of extraterritoriality.','历史课包含了关于治外法权的讨论。'),('The article examines the extraterritoriality of the proposed rules.','文章讨论了拟议规则的域外适用问题。'),sources=['https://www.merriam-webster.com/dictionary/extraterritoriality']),
E('terrain','/təˈreɪn/','地形；地面状况','脚下是平地、山坡、泥泞还是乱石，走起来到底是什么感觉。','法语 terrain 接拉丁 terrenum，来自 terrenus“土地的”，再接 terra。',TR,'rough terrain 是崎岖地形；mountainous terrain 是山地地形。比喻 unfamiliar terrain 时也可说陌生的知识领域，但基本画面仍是你正走过怎样一片地方。','rough terrain；flat terrain；mountainous terrain。','territory 关心范围、归属或控制；terrain 关心地表的形状与条件，同一片地可以从两种角度描述。',('The vehicle was designed for rough terrain.','这辆车是为崎岖地形设计的。'),('The map helped us understand the terrain ahead.','地图帮助我们了解前方的地形。'),sources=['https://www.etymonline.com/word/terrain']),
E('terrane','/təˈreɪn/','地体；特定岩石区〔地质〕','一块岩石区域有自己的地质经历，像拼图的一片，不一定与旁边的经历相同。','terrain 的拼写变体，后来用于特定地质区域和地体概念。',A(TR,'英语 terrain → terrane','地形、地区的名称变体 → 地质区域、地体'),'现代构造地质学里，terrane 常指以断层等为界、地质历史与邻区不同的岩块。较宽用法也可说某类岩石分布的区域。它不只是把普通 terrain 换个更专业的拼写。','a tectonic terrane；terrane boundaries；an accreted terrane。','terrain 更常说地面起伏；terrane 在地质分析中更关注岩石组合和历史。两词读音可一样。',('The geologists mapped the boundary between the two terranes.','地质学家绘出了两个地体之间的界线。'),('The terrane preserves a history different from that of the surrounding rocks.','这个地体保留着与周围岩石不同的地质历史。'),sources=['https://www.merriam-webster.com/dictionary/terrane','https://pubs.usgs.gov/of/1998/of98-136/doc/html/gnotes.htm']),
E('terrace','/ˈterəs/','露台；台地、梯田；连排住宅','把斜坡切出一块平平的台面，或把建筑外面做出一片可站可坐的平台。','经法语 terrasse 接重建的通俗拉丁 *terracea“土的”，来自 terra。',TC,'a terrace outside a café 是咖啡馆外的露台；rice terraces 是一层层梯田。英国英语里的 a terrace of houses 是一排彼此相连的住宅，不是每户必须带阳台。','sit on the terrace；rice terraces；a terrace of houses。','balcony 通常是伸出建筑外的阳台；terrace 常是较开阔的平台。具体建筑中两者的形式可能相近。',('We had lunch on the terrace overlooking the garden.','我们在俯瞰花园的露台上吃了午饭。'),('The hillside was shaped into terraces for farming.','山坡被整成了便于耕种的梯田。'),sources=['https://www.etymonline.com/word/terrace']),
E('terraced','/ˈterəst/','梯田式的；筑成台地的；连排的〔住宅〕','斜坡被整理成一层层台阶，或房屋一户接一户连成一排。','terrace + -d；词尾 /s/ 后的 -ed 读 /t/。',A(TC,'英语 terraced','形成台地、梯田的；属于连排住宅的'),'a terraced hillside 是梯田式山坡；a terraced house 在英国英语里是连排住宅的一户。两种用法同属 terrace 的支线，不能只看中文“梯田”去想象房屋必在山上。','terraced fields；a terraced house；terraced gardens。','detached house 是独栋住宅；terraced house 与相邻住宅相连。terraced fields 则说土地分层的形态。',('The path winds through terraced fields.','小路蜿蜒穿过层层梯田。'),('They live in a terraced house near the station.','他们住在车站附近的一栋连排住宅里。')),
E('terracing','/ˈterəsɪŋ/','修筑梯田或台地；梯田、阶梯式平台','把连续的斜坡变成一层层较平的台面，也可指做好的整片结构。','terrace 去词尾 e + -ing。',A(TC,'英语 terracing','修筑台地的过程；台地、阶梯结构'),'agricultural terracing 是农业梯田化；stadium terracing 可以说阶梯式看台区域。词形既能指施工过程，也能指留下来的台阶状结构。','terracing on a slope；ancient terracing；stadium terracing。','terrace 可指一层平台；terracing 常指修筑行为或多层组成的结构。',('The old terracing is still visible on the hillside.','山坡上仍能看见古老梯田的痕迹。'),('The project includes terracing the steep garden.','这个项目包括把陡坡花园整理成台地。')),
E('terrarium','英 /təˈreəriəm/；美 /təˈreriəm/','玻璃生态箱；陆生动植物饲养、栽培箱','把一小块陆地环境搬进透明容器，让你能在桌边观察。','拉丁 terra“土地” + -arium“容纳、供……用的场所”，仿 aquarium 的形式造词。',T+[['terra + -arium，参照 aquarium','土地 + 容纳环境的空间'],['英语 terrarium','栽培植物或饲养陆生小动物的容器、箱体']],'植物 terrarium 常是放有土、植物等的玻璃容器，也有用于陆生动物的生态箱。它不要求里面装满水；不同用途需要不同布置，名称本身不会说明具体生态条件。','a glass terrarium；plants in a terrarium；a terrarium display。','aquarium 以水环境为核心；terrarium 以陆地环境为核心。二者都是容器名称，不是某一种植物或动物。',('She arranged small plants inside a glass terrarium.','她把小植物布置在一个玻璃生态瓶里。'),('The museum uses a terrarium to display a miniature woodland habitat.','博物馆用生态箱展示一个微缩的林地环境。'),sources=['https://en.wiktionary.org/wiki/terrarium']),
E('terracotta','英 /ˌterəˈkɒtə/；美 /ˌterəˈkɑːtə/','赤陶；陶土制品；赤陶色','把泥土烧硬，留下温暖的红褐色，这就是“烧过的土”的画面。','意大利 terra“土” + cotta“烧熟、烘焙过的”，合起来是烧过的土。',T+[['意大利 terra + cotta → terracotta','土 + 烧过的 → 烧制陶土'],['英语 terracotta','赤陶材料、制品；相应红褐色']],'terracotta pots 是赤陶花盆；terracotta tiles 是陶土砖瓦。颜色用法说类似陶土的暖红褐色；看到这种颜色并不代表物品真的由陶土烧成。','terracotta pots；terracotta tiles；a terracotta colour。','ceramic 是更宽的陶瓷类别；terracotta 通常说特定的烧制陶土材料或其颜色。',('The courtyard was lined with terracotta pots.','庭院两边摆着赤陶花盆。'),('They painted the wall a warm terracotta colour.','他们把墙刷成了温暖的陶土红褐色。'),sources=['https://en.wiktionary.org/wiki/terracotta']),
]
